compliant.code:
import boto3

# Good: Explicit HTTPS configuration
s3 = boto3.client('s3',
                 use_ssl=True,  # Explicit HTTPS enforcement
                 config=boto3.session.Config(signature_version='s3v4'))

# Good: Bucket policy enforces HTTPS (shown conceptually)
bucket_policy = {
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Deny",
            "Principal": "*",
            "Action": "s3:*",
            "Resource": ["arn:aws:s3:::my-bucket/*"],
            "Condition": {
                "Bool": {"aws:SecureTransport": "false"}
            }
        }
    ]
}

noncompliant.code:
from boto3.s3.transfer import S3Transfer

# Bad: Transfer configuration without HTTPS enforcement
transfer_config = S3Transfer(
    client=boto3.client('s3', use_ssl=False),  # Security Hotspot
    config={}
)
